using UnityEngine;
namespace LWS.TruckTerrierRacing {
// UTS owns running animation/path locomotion; Taxi owns jointed impact response. This adapter owns race placement/pooling/replay.
public sealed class TerrierCrowd:MonoBehaviour {
 public TerrierMatch match;public TerrierRunner[] runners;public WalkPath[] paths;public Transform[] ghosts;public int Hits;
 struct Pose {public Vector3 p;public Quaternion q;}
 Transform[][] live,recorded;Pose[] roots,parts;int[] masks,offsets;int partCount;bool replaying;
 void Start(){if(!match.Running)foreach(var runner in runners){runner.walker.enabled=false;runner.GetComponent<Rigidbody>().isKinematic=true;}}
 void Initialize(){if(live!=null)return;live=new Transform[runners.Length][];recorded=new Transform[runners.Length][];offsets=new int[runners.Length];for(int i=0;i<runners.Length;i++){live[i]=runners[i].GetComponentsInChildren<Transform>(true);recorded[i]=ghosts[i].GetChild(0).GetComponentsInChildren<Transform>(true);if(live[i].Length!=recorded[i].Length)throw new System.InvalidOperationException("Pedestrian replay hierarchy differs");offsets[i]=partCount;partCount+=live[i].Length;}int capacity=Mathf.Clamp(match.replay.capacity,2200,2400);roots=new Pose[capacity*runners.Length];parts=new Pose[capacity*partCount];masks=new int[capacity];}
 public void ResetHeat(){Initialize();Hits=0;replaying=false;for(int i=0;i<runners.Length;i++){float z=20+i*12.6f;float width=Mathf.Max(2,match.course.HalfWidth(z)-3);var path=paths[i];for(int k=0;k<4;k++){var local=new Vector3(k<2?-width:width,0,z+(k==0||k==3?-1.8f:1.8f));path.pathPointTransform[k].transform.position=match.course.World(local);path.pathPoint[k]=path.pathPointTransform[k].transform.position;}path.DrawCurved(false);var runner=runners[i];int point=i%4;runner.pedestrian.Reactivate(path.getNextPoint(0,point+1),match.course.DrivingRotation,"terrier.runner."+i,true);runner.pedestrian.settings.ragdollLifetime=6;runner.walker.ANIMATION_STATE=runner.walker.LastState=PeopleAnimState.run;runner.walker.RUN_SPEED=3.6f+i%3*.6f;runner.walker.enabled=false;runner.detector.enabled=true;runner.movement.InitStartPosition(0,point+1,true,true);runner.movement.SetLookPosition();ghosts[i].gameObject.SetActive(false);}}
 public void Step(float dt){if(replaying)return;foreach(var runner in runners){if(!runner.gameObject.activeSelf||runner.pedestrian.IsRagdoll)continue;runner.walker.enabled=true;var p=match.course.Local(runner.transform.position);runner.transform.position=match.course.World(new Vector3(p.x,0,p.z));}}
 public void Record(int frame){int mask=0;for(int i=0;i<runners.Length;i++){if(runners[i].gameObject.activeSelf)mask|=1<<i;roots[frame*runners.Length+i]=new Pose{p=runners[i].transform.position,q=runners[i].transform.rotation};for(int k=0;k<live[i].Length;k++)parts[frame*partCount+offsets[i]+k]=new Pose{p=k==0?Vector3.zero:live[i][k].localPosition,q=k==0?Quaternion.identity:live[i][k].localRotation};}masks[frame]=mask;}
 public void BeginReplay(){replaying=true;foreach(var runner in runners)runner.gameObject.SetActive(false);}
 public void DrawReplay(int lo,int hi,float t){for(int i=0;i<runners.Length;i++){bool visible=(masks[lo]&(1<<i))!=0;ghosts[i].gameObject.SetActive(visible);if(!visible)continue;var a=roots[lo*runners.Length+i];var b=roots[hi*runners.Length+i];ghosts[i].SetPositionAndRotation(Vector3.Lerp(a.p,b.p,t),Quaternion.Slerp(a.q,b.q,t));for(int k=0;k<recorded[i].Length;k++){a=parts[lo*partCount+offsets[i]+k];b=parts[hi*partCount+offsets[i]+k];recorded[i][k].SetLocalPositionAndRotation(Vector3.Lerp(a.p,b.p,t),Quaternion.Slerp(a.q,b.q,t));}}}
 public void EndReplay(){foreach(var ghost in ghosts)ghost.gameObject.SetActive(false);replaying=false;}
 public void Stop(){if(runners!=null)foreach(var runner in runners)runner.gameObject.SetActive(false);if(ghosts!=null)foreach(var ghost in ghosts)ghost.gameObject.SetActive(false);}
}
}
